using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using GameActions;
namespace AssetPipeline.Editor
{
 public static partial class AdvancedCombatVFXSetup
 {
  [InitializeOnLoadMethod]static void ImpactWatch(){EditorApplication.update+=()=>{if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists(Stage+"ImpactBuild.request"))return;File.Delete(Stage+"ImpactBuild.request");try{BuildGroundImpact();File.WriteAllText(Stage+"impact_build.json","{\"passed\":true}");}catch(Exception e){File.WriteAllText(Stage+"impact_build.json",e.ToString());Debug.LogException(e);}};}
  static Mesh Rock()
  {
   string path=Root+"ConcreteFragment.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh)return mesh;mesh=new Mesh{name="Chipped concrete fragment 12 triangles"};var v=new[]{new Vector3(-.6f,-.3f,-.4f),new Vector3(.5f,-.24f,-.45f),new Vector3(.4f,.36f,-.3f),new Vector3(-.4f,.3f,-.42f),new Vector3(-.5f,-.18f,.32f),new Vector3(.4f,-.3f,.35f),new Vector3(.6f,.22f,.46f),new Vector3(-.35f,.26f,.4f)};var ids=new[]{0,2,1,0,3,2,1,2,6,1,6,5,5,6,7,5,7,4,4,7,3,4,3,0,3,7,6,3,6,2,4,0,1,4,1,5};mesh.vertices=ids.Select(i=>v[i]).ToArray();mesh.triangles=Enumerable.Range(0,ids.Length).ToArray();mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,path);return mesh;
  }
  static GameObject ImpactPrefab(bool heavy,Material dustMat,Material stoneMat)
  {
   string name=heavy?"ConcreteImpactHeavy":"ConcreteImpactLight";var root=new GameObject(name);
   var ring=PS(root,"Expanding ground dust",dustMat,heavy?30:18,3.2f,0,heavy?1.15f:.75f,new Color(.44f,.42f,.39f,.5f));Sheet(ring);Grow(ring,2.4f);var shape=ring.shape;shape.shapeType=ParticleSystemShapeType.Circle;shape.radius=heavy?.5f:.25f;shape.rotation=new Vector3(-90,0,0);var velocity=ring.velocityOverLifetime;velocity.enabled=true;velocity.space=ParticleSystemSimulationSpace.World;velocity.radial=new ParticleSystem.MinMaxCurve(1,new AnimationCurve(new Keyframe(0,heavy?5:3),new Keyframe(.4f,1),new Keyframe(1,.1f)));velocity.y=.22f;var noise=ring.noise;noise.enabled=true;noise.strength=.3f;noise.frequency=.6f;noise.scrollSpeed=.3f;
   var plume=PS(root,"Impact dust lift",dustMat,heavy?12:6,2.5f,heavy?2.5f:1.6f,heavy?1.1f:.7f,new Color(.4f,.38f,.35f,.45f));Sheet(plume);Grow(plume,2);shape=plume.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.rotation=new Vector3(-90,0,0);shape.angle=35;shape.radius=.3f;var drag=plume.limitVelocityOverLifetime;drag.enabled=true;drag.limit=.8f;drag.dampen=.25f;
   var pieces=PS(root,"Colliding concrete chunks",stoneMat,heavy?36:18,6.5f,heavy?7:4.5f,heavy?.22f:.15f,Color.white);var main=pieces.main;main.gravityModifier=1.3f;main.startRotation3D=true;main.startRotationX=new ParticleSystem.MinMaxCurve(0,6.28f);main.startRotationY=main.startRotationX;main.startRotationZ=main.startRotationX;shape=pieces.shape;shape.shapeType=ParticleSystemShapeType.Hemisphere;shape.rotation=new Vector3(-90,0,0);shape.radius=.2f;Collide(pieces,.25f);var rotation=pieces.rotationOverLifetime;rotation.enabled=true;rotation.separateAxes=true;rotation.x=new ParticleSystem.MinMaxCurve(-3,3);rotation.y=new ParticleSystem.MinMaxCurve(-2,2);rotation.z=rotation.x;var renderer=pieces.GetComponent<ParticleSystemRenderer>();renderer.renderMode=ParticleSystemRenderMode.Mesh;renderer.mesh=Rock();var fade=pieces.colorOverLifetime;fade.enabled=true;var g=new Gradient();g.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(Color.white,1)},new[]{new GradientAlphaKey(1,0),new GradientAlphaKey(1,.8f),new GradientAlphaKey(0,1)});fade.color=g;
   CombatImpactTuning.Configure(root,heavy);return Save(root,name);
  }
  static void BuildGroundImpact()
  {
   var dust=Mat("ConcreteDust","Universal Render Pipeline/Particles/Unlit",Color.white,Load<Texture2D>("Textures/Smoke_07_loop_8x8.tga"));dust.SetFloat("_SoftParticlesEnabled",1);dust.EnableKeyword("_SOFTPARTICLES_ON");dust.SetVector("_SoftParticleFadeParams",new Vector4(0,1,0,0));
   var stone=Mat("ConcreteFragments","Universal Render Pipeline/Particles/Lit",new Color(.3f,.29f,.27f));stone.SetFloat("_Smoothness",.08f);stone.SetFloat("_Metallic",0);stone.SetFloat("_Cull",2);
   var light=ImpactPrefab(false,dust,stone);var heavy=ImpactPrefab(true,dust,stone);var library=AssetDatabase.LoadAssetAtPath<CombatEffectLibrary>("Assets/Game/Shared/Actions/Resources/CombatVFX.asset");var entries=library.effects.Where(e=>e.kind!=CombatEffect.ConcreteImpactLight&&e.kind!=CombatEffect.ConcreteImpactHeavy).ToList();entries.Add(new CombatEffectPrefab{kind=CombatEffect.ConcreteImpactLight,prefab=light,lifetime=8});entries.Add(new CombatEffectPrefab{kind=CombatEffect.ConcreteImpactHeavy,prefab=heavy,lifetime=8});library.effects=entries.ToArray();EditorUtility.SetDirty(library);string bossPath="Assets/Game/Enemies/UDK7M/AI/Prefabs/UDK7MBoss.prefab";var boss=PrefabUtility.LoadPrefabContents(bossPath);try{var decals=boss.GetComponent<GroundImpactDecals>();decals.lightDebris=light;decals.heavyDebris=heavy;PrefabUtility.SaveAsPrefabAsset(boss,bossPath);}finally{PrefabUtility.UnloadPrefabContents(boss);}
   foreach(var decals in UnityEngine.Object.FindObjectsByType<GroundImpactDecals>(FindObjectsInactive.Include,FindObjectsSortMode.None)){decals.lightDebris=light;decals.heavyDebris=heavy;EditorUtility.SetDirty(decals);EditorSceneManager.MarkSceneDirty(decals.gameObject.scene);}
   foreach(var path in new[]{"VioletCrystalDebris.prefab","Sparks.prefab"}){var asset=PrefabUtility.LoadPrefabContents(Root+path);try{foreach(var ps in asset.GetComponentsInChildren<ParticleSystem>()){if(path=="Sparks.prefab"){var r=ps.GetComponent<ParticleSystemRenderer>();r.velocityScale=.035f;r.lengthScale=2;}if(ps.collision.enabled){var c=ps.collision;c.quality=ParticleSystemCollisionQuality.High;c.enableDynamicColliders=true;}}PrefabUtility.SaveAsPrefabAsset(asset,Root+path);}finally{PrefabUtility.UnloadPrefabContents(asset);}}
   AssetDatabase.SaveAssets();
  }
 }
}
